import{R as e,e as o,f as n,U as r}from"./chunks/framework.ywem4qy5.js";const d=JSON.parse('{"title":"Intercom","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/help-desk/intercom.md","filePath":"integrations/help-desk/intercom.md","lastUpdated":1775908585000}'),i={name:"integrations/help-desk/intercom.md"};function a(s,t,l,c,h,g){return o(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="intercom" tabindex="-1">Intercom <a class="header-anchor" href="#intercom" aria-label="Permalink to &quot;Intercom&quot;">​</a></h1><p>Follow the below steps to connect to the Intercom API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Help Desk</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>Intercom</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-intercom-api" tabindex="-1">Step 2. Connect to the Intercom API <a class="header-anchor" href="#step-2-connect-to-the-intercom-api" aria-label="Permalink to &quot;Step 2. Connect to the Intercom API&quot;">​</a></h3><ol><li>Go to <a href="https://www.intercom.com/" target="_blank">Intercom</a> and log into your account.</li><li>Visit your <strong>Intercom Developer Hub</strong> at <a href="https://app.intercom.com/a/apps/_/developer-hub" target="_blank"><a href="https://app.intercom.com/a/apps/_/developer-hub" target="_blank" rel="noreferrer">https://app.intercom.com/a/apps/_/developer-hub</a></a>.</li><li>Click <strong>New App</strong>, and provide an app name (e.g. <code>Formie</code>) and select your workspace.</li><li>Click the <strong>Edit</strong> button.</li><li>In the <strong>Redirect URLs</strong> field, enter the value from the <strong>Redirect URI</strong> field in Formie.</li><li>In the left-hand sidebar menu, go to <strong>Basic Information</strong>.</li><li>Copy the <strong>Client ID</strong> from Intercom and paste in the <strong>Client ID</strong> field in Formie.</li><li>Copy the <strong>Client Secret</strong> from Intercom and paste in the <strong>Client Secret</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-settings" tabindex="-1">Step 4. Form Settings <a class="header-anchor" href="#step-4-form-settings" aria-label="Permalink to &quot;Step 4. Form Settings&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const m=e(i,[["render",a]]);export{d as __pageData,m as default};
